var COM = {"0": "<p>Certo. Art. 125.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "1": "<p>Errado. Incidem sobre as alíquotas-padrão de cada ente federativo (art. 126, § 4º).</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "2": "<p>Errado. A revisão serve somente para inclusão de itens novos que atendam às mesmas finalidades.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "3": "<p>Certo. 26,5 x 0,40 = 10,6.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "4": "<p>Certo. Título do Anexo I e art. 148.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "5": "<p>Errado. O pão de forma está no Anexo VII, com redução de 60%.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "6": "<p>Errado. O item 20 exclui salmonídeos, atuns, bacalhaus, hadoque e saithe.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "7": "<p>Certo. Item 24.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "8": "<p>Certo. Item 30 do Anexo III.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "9": "<p>Errado. Só aos valores da contraprestação dos serviços listados.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "10": "<p>Certo. Item 6.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "11": "<p>Certo. Art. 130, parágrafo único.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "12": "<p>Errado. Art. 131, § 1º: somente os regularizados.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "13": "<p>Certo. Art. 133, caput.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "14": "<p>Certo. Art. 133, § 2º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "15": "<p>Errado. Cadeiras de rodas estão no Anexo XIII, com alíquota zero.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "16": "<p>Certo. Art. 137, caput.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "17": "<p>Certo. Art. 147 e Anexo VIII, item 7.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "18": "<p>Certo. Art. 138, § 1º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "19": "<p>Errado. O § 1º do art. 137 define in natura como produto sem embalagem de apresentação.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "20": "<p>Errado. Só ao fornecimento à administração pública direta, autarquias e fundações (art. 140).</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "21": "<p>Certo. Itens do Anexo X.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "22": "<p>Certo. Art. 142, II.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "23": "<p>Certo. Constam como (VETADO).</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>"};
